/* Large-data UX simulation. Filtering/pagination here are client-side only. */
const demoToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let listPage=1,listSize=mobile?8:20,listKind='Daftar',listQuery='',listOwner='',listStatus='',listSource='',listProduct='',listRelation='',listGrade='',agendaRange='Hari ini',agendaType='',listPeriod='',calendarExpanded=false,searchTimer;
const stagePages={};
function resetLists(){stageFilter='';sourceFilter='';listPage=1;listQuery='';listOwner='';listStatus='';listSource='';listProduct='';listRelation='';listGrade='';listPeriod='';agendaType='';agendaRange='Hari ini';calendarDate='';calendarExpanded=false}
const scaleGo=go;
go=function(v,id=''){resetLists();scaleGo(v,id)};
function changeFilter(name,value){if(name==='owner')listOwner=value;if(name==='status'){listStatus=value;if(value&&value!=='Aktif')listKind='Daftar';}if(name==='source')listSource=value;if(name==='product')listProduct=value;if(name==='relation')listRelation=value;if(name==='grade')listGrade=value;if(name==='period')listPeriod=value;if(name==='type')agendaType=value;listPage=1;renderContent()}
function largeSearch(value){listQuery=value;listPage=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{renderContent();const input=$('#listSearch');input?.focus();input?.setSelectionRange(value.length,value.length)},180)}
function pageItems(items){const pages=Math.max(1,Math.ceil(items.length/listSize));listPage=Math.min(Math.max(1,listPage),pages);return items.slice((listPage-1)*listSize,listPage*listSize)}
function pager(total){let pages=Math.max(1,Math.ceil(total/listSize)),first=total?(listPage-1)*listSize+1:0,last=Math.min(total,listPage*listSize);return `<div class="pagination"><span>${first.toLocaleString('id-ID')}-${last.toLocaleString('id-ID')} dari ${total.toLocaleString('id-ID')}</span><div><button ${listPage<=1?'disabled':''} onclick="listPage--;renderContent();document.querySelector('main')?.scrollTo(0,0)">‹</button><b>${listPage} / ${pages}</b><button ${listPage>=pages?'disabled':''} onclick="listPage++;renderContent();document.querySelector('main')?.scrollTo(0,0)">›</button></div></div>`}
function filterSelect(label,name,values,current){return `<select aria-label="${label}" onchange="changeFilter('${name}',this.value)"><option value="">${label}</option>${values.map(v=>`<option value="${E(v)}" ${current===v?'selected':''}>${E(v)}</option>`).join('')}</select>`}
function commonFilters(extra=''){return `<div class="scaletools"><div class="searchbox"><span>⌕</span><input id="listSearch" aria-label="Cari daftar" placeholder="Cari nama, kebutuhan, atau ID…" value="${E(listQuery)}" oninput="largeSearch(this.value)"></div><div class="filterline">${supervisors()?filterSelect('Semua AO','owner',owners,listOwner):''}${extra}${btn('Reset filter','resetLists();renderContent()')}</div></div>`}
function localMatches(x,...labels){return mine(x)&&(!listOwner||x.owner===listOwner)&&(!listQuery||labels.join(' ').toLowerCase().includes(listQuery.toLowerCase()))}
function sortPriority(a,b){return Number(overdue(b))-Number(overdue(a))||a.scheduled.localeCompare(b.scheduled)||a.id.localeCompare(b.id)}
function getList(viewName=view){if(viewName==='Leads')return db.leads.filter(l=>localMatches(l,pname(l.profile),l.need,l.id,profile(l.profile)?.phone)&&(!listStatus?!['Converted','Closed','CustomerConverted'].includes(l.status):listStatus==='Semua'||l.status===listStatus)&&(!listSource||l.source===listSource)&&(!listGrade||l.grade===listGrade)&&(!listPeriod||l.created.startsWith(listPeriod))).sort((a,b)=>b.created.localeCompare(a.created)||a.id.localeCompare(b.id));if(viewName==='Peluang')return db.opps.filter(o=>localMatches(o,o.name,pname(o.profile),o.id)&&(!listStatus?o.outcome==='Aktif':listStatus==='Semua'||o.outcome===listStatus)&&(!listProduct||o.product===listProduct)&&(!stageFilter||o.stage===stageFilter)&&(!listPeriod||o.created.startsWith(listPeriod))).sort((a,b)=>Number(overSla(b))-Number(overSla(a))||a.closing.localeCompare(b.closing)||a.id.localeCompare(b.id));if(viewName==='Nasabah')return db.profiles.filter(p=>p.relation==='Customer'&&localMatches(p,p.name,p.contact,p.phone,p.id)).sort((a,b)=>a.name.localeCompare(b.name));return db.tasks.filter(t=>{if(!localMatches(t,t.purpose,pname(t.profile),t.id,opp(t.opp)?.name)||agendaType&&t.type!==agendaType)return false;let d=t.scheduled.slice(0,10),today=demoToday();if(calendarExpanded&&calendarDate)return d===calendarDate;if(agendaRange==='Riwayat')return !isOpen(t);if(!isOpen(t))return false;if(agendaRange==='Overdue')return overdue(t);if(agendaRange==='Hari ini')return d===today;if(agendaRange==='7 hari')return d>=today&&d<=new Date(Date.now()+7*86400000).toISOString().slice(0,10);return true}).sort(sortPriority)}
function contextLabel(t){let o=opp(t.opp);return `<div class="contextline">${o?`<span class="contextpill">Opportunity</span><span>${E(o.name)}</span>`:t.lead?`<span class="contextpill">Penjajakan</span><span>Lead ${E(t.lead)}</span>`:`<span class="contextpill">Relationship</span><span>Aktivitas umum</span>`}</div>`}
const taskCardBeforeScale=taskCard;
taskCard=function(t){let html=taskCardBeforeScale(t);return html.replace('<div class="meta">',contextLabel(t)+'<div class="meta">').replace('<h3>',`<h3>${activityKind(t.type)==='Kunjungan'?`<small class="approvalhint">${E(t.approval||'Menunggu')}</small>`:''}`)};
function taskRows(items){return `<div class="scrolltable"><table class="datatable"><thead><tr><th>Aktivitas & konteks</th><th>Lead / Nasabah</th><th>Jadwal / deadline</th><th>AO</th><th>Status</th><th></th></tr></thead><tbody>${items.map(t=>`<tr><td><strong>${E(t.purpose)}</strong><small>${E(t.type)} · ${E(t.id)}</small>${contextLabel(t)}</td><td><strong>${E(pname(t.profile))}</strong><small>${E(profile(t.profile)?.relation)}</small></td><td><strong>${fmt(t.scheduled)}</strong><small>Batas ${fmt(t.due)}</small></td><td>${E(t.owner)}</td><td>${badge(overdue(t)?'Overdue':t.status)}${activityKind(t.type)==='Kunjungan'?`<small>${E(t.approval||'Menunggu')}</small>`:''}</td><td>${btn('Buka',`go('Aktivitas detail','${t.id}')`)}</td></tr>`).join('')}</tbody></table></div>`}
function leadRows(items){return `<div class="scrolltable"><table class="datatable"><thead><tr><th>Lead</th><th>Kebutuhan</th><th>Sumber</th><th>Kualifikasi</th><th>Owner</th><th></th></tr></thead><tbody>${items.map(l=>`<tr><td><strong>${E(pname(l.profile))}</strong><small>${E(l.id)} · ${fmt(l.created)}</small></td><td>${E(l.need)}<small>${E(l.product)}</small></td><td>${E(l.source)}<small>${E(l.referral||'')}</small></td><td>${badge(l.grade)}<small>${E(l.qualification)} · ${E(l.status)}</small></td><td>${E(l.owner)}</td><td>${btn('Detail',`go('Lead detail','${l.id}')`)}</td></tr>`).join('')}</tbody></table></div>`}
function oppRows(items){return `<div class="scrolltable"><table class="datatable"><thead><tr><th>Peluang</th><th>Stage / SLA</th><th>Nilai indikatif</th><th>Probability</th><th>Owner / closing</th><th></th></tr></thead><tbody>${items.map(o=>`<tr><td><strong>${E(o.name)}</strong><small>${E(pname(o.profile))} · ${E(o.id)}</small></td><td>${badge(o.stage)}<small>${age(o)} / ${stageLimit(o)} hari ${overSla(o)?'· Over SLA':''}</small></td><td><strong>${rup(o.value)}</strong><small>${E(o.basis)}</small></td><td>${o.probability??0}%<small>${E(o.outcome)}</small></td><td>${E(o.owner)}<small>${fmt(o.closing)}</small></td><td>${btn('Detail',`go('Opportunity detail','${o.id}')`)}</td></tr>`).join('')}</tbody></table></div>`}
function mobileLead(l){return `<article class="record"><div class="recordtop">${badge(l.status)}${badge(l.grade)}</div><h3>${E(pname(l.profile))}</h3><p>${E(l.need)}</p><div class="meta">${E(l.source)} · ${E(l.owner)}<br>${E(l.qualification)} · ${fmt(l.created)}</div>${btn('Buka lead',`go('Lead detail','${l.id}')`)}</article>`}
function profileCard(p){return `<article class="record"><div class="recordtop">${badge(p.relation)}<small>${E(p.id)}</small></div><h3>${E(p.name)}</h3><p>${E(p.contact)} · ${E(p.phone)}</p><small>${E(p.owner)}</small><div class="actions">${btn('Nasabah',`go('Nasabah detail','${p.id}')`)}${btn('Opportunity',`newOpp('${p.id}')`)}</div></article>`}
function denseBoard(items){return `<div class="board">${stages.map(s=>{let a=items.filter(o=>o.stage===s);return `<section class="column"><div class="columnhead"><b>${s}</b><span>${a.length}</span></div>${a.slice(0,5).map(oppCard).join('')||empty('Belum ada peluang.')}${a.length>5?btn('Lihat '+a.length+' peluang',`stageFilter='${s}';listKind='Daftar';listPage=1;renderContent()`):''}</section>`}).join('')}</div><p class="hint">Pipeline menampilkan maksimal 5 kartu prioritas per tahap. Buka daftar tahap untuk seluruh record.</p>`}
function scaleList(){let items=getList(),slice=pageItems(items),html='';if(view==='Agenda'){let all=visible(db.tasks),current=demoToday();html+=titleBlock('Task','Rencana dan hasil aktivitas terhubung pada lead/nasabah serta opportunity jika ada.',btn('Tambah Task','newTask()',true));html+=`<div class="rangechips">${['Hari ini','Overdue','7 hari','Semua aktif','Riwayat'].map(r=>`<button class="${agendaRange===r?'active':''}" onclick="agendaRange='${r}';listPage=1;calendarDate='';renderContent()">${r}<b>${r==='Hari ini'?all.filter(t=>isOpen(t)&&t.scheduled.startsWith(current)).length:r==='Overdue'?all.filter(overdue).length:r==='Riwayat'?all.filter(t=>!isOpen(t)).length:''}</b></button>`).join('')}</div>`+commonFilters(filterSelect('Semua aktivitas','type',['Telepon','Kunjungan','Meeting','Cek dokumen'],agendaType))+`<div class="listhead"><strong>${items.length.toLocaleString('id-ID')} aktivitas</strong>${btn(calendarExpanded?'Tutup kalender':'Kalender',"calendarExpanded=!calendarExpanded;calendarDate='';renderContent()")}</div>`+(calendarExpanded?calendarView():'');html+=items.length?(mobile?`<div class="records">${slice.map(taskCard).join('')}</div>`:taskRows(slice)):empty('Tidak ada aktivitas sesuai filter. Coba hari atau status lain.');}
if(view==='Leads'){html+=titleBlock('Leads','Penjajakan lead dan kebutuhan awal.',btn('Lead baru','createLead()',true))+commonFilters(filterSelect('Lead aktif','status',['Semua','New','In qualification','Converted','Closed'],listStatus)+filterSelect('Semua sumber','source',[...new Set(db.leads.map(l=>l.source))],listSource)+filterSelect('Semua kategori','grade',quals,listGrade)+`<input aria-label="Bulan lead dibuat" type="month" value="${listPeriod}" onchange="changeFilter('period',this.value)">`)+`<div class="listhead"><strong>${items.length.toLocaleString('id-ID')} lead sesuai filter</strong></div>`;html+=items.length?(mobile?`<div class="records">${slice.map(mobileLead).join('')}</div>`:leadRows(slice)):empty('Tidak ada lead sesuai filter.');}
if(view==='Peluang'){html+=titleBlock('Opportunity','Setiap kebutuhan memiliki progres dan tindak lanjut sendiri.',btn('Opportunity baru','newOpp()',true))+commonFilters(filterSelect('Peluang aktif','status',['Semua','Aktif','Won','Lost','Cancelled'],listStatus)+filterSelect('Semua produk','product',[...new Set(db.opps.map(o=>o.product))],listProduct)+`<select aria-label="Tahap peluang" onchange="stageFilter=this.value;listPage=1;renderContent()"><option value="">Semua tahap</option>${options(stages,stageFilter)}</select>`)+`<div class="listhead"><strong>${items.length.toLocaleString('id-ID')} opportunity</strong><div class="viewtoggle">${['Daftar','Pipeline'].map(k=>`<button class="${listKind===k?'active':''}" onclick="listKind='${k}';if(listKind==='Pipeline')listStatus='Aktif';renderContent()">${k}</button>`).join('')}</div></div>`;html+=listKind==='Pipeline'?denseBoard(items):items.length?(mobile?`<div class="records">${slice.map(oppCard).join('')}</div>`:oppRows(slice)):empty('Tidak ada opportunity sesuai filter.');}
if(view==='Nasabah'){html+=titleBlock('Nasabah','Kelola nasabah existing, peluang bisnis dan riwayat hubungan.',btn('Buat Nasabah','directCustomer()',true))+commonFilters()+`<div class="listhead"><strong>${items.length.toLocaleString('id-ID')} nasabah</strong></div>`+`<div class="records">${slice.map(profileCard).join('')||empty('Belum ada nasabah yang sesuai dengan pencarian.')}</div>`;}
return html+(view==='Peluang'&&listKind==='Pipeline'?'':pager(items.length))+`<div class="listnote">${mobile?'8':'20'} record per halaman</div>`}
function largeMonitor(){let os=visible(db.opps).filter(o=>o.outcome==='Aktif'),ts=visible(db.tasks),dues=ts.filter(overdue).sort(sortPriority),missing=os.filter(o=>!hasNext(o)),stale=os.filter(overSla),uncontacted=visible(db.leads).filter(l=>!['Converted','Closed','CustomerConverted'].includes(l.status)&&!db.activities.some(a=>a.lead===l.id));return titleBlock('Prioritas tim hari ini','Ringkasan masalah dulu, detail saat dibutuhkan.',btn('Tambah Task','newTask()',true))+`<div class="metrics">${[['Opportunity aktif',os.length,"go('Peluang')"],['Follow-up overdue',dues.length,"go('Agenda');agendaRange='Overdue';renderContent()"],['Over SLA tahap',stale.length,"go('Notifikasi')"],['Menunggu approval',pendingApprovals().length,"go('Persetujuan')"]].map(([a,b,act])=>`<button class="metric" onclick="${act}"><span>${a}</span><strong>${b.toLocaleString('id-ID')}</strong><small>Buka daftar ↗</small></button>`).join('')}</div><div class="split"><section class="panel"><div class="listhead"><h2>Overdue yang perlu ditangani</h2><small>${Math.min(5,dues.length)} dari ${dues.length}</small></div>${dues.slice(0,5).map(taskCard).join('')||empty('Tidak ada overdue.')}${dues.length>5?btn('Lihat semua overdue',"go('Agenda');agendaRange='Overdue';renderContent()"):''}</section><section class="panel"><h2>Pipeline aktif per tahap</h2>${stages.map(s=>`<button class="stagebar" onclick="go('Peluang');stageFilter='${s}';renderContent()"><span>${s}</span><i style="width:${Math.max(4,os.filter(o=>o.stage===s).length/Math.max(1,os.length)*60)}%"></i><b>${os.filter(o=>o.stage===s).length}</b></button>`).join('')}<div class="summaryrow"><b>Belum kontak pertama</b><span>${uncontacted.length} lead</span></div><div class="summaryrow"><b>Tanpa next action</b><span>${missing.length} opportunity</span></div><div class="actions">${btn('Reminder & eskalasi',"go('Notifikasi')")}${btn('Laporan',"go('Laporan')")}</div><p class="hint">Ringkasan seluruh data dalam kewenangan Anda.</p></section></div>`}
function scaleApprovals(){let a=pendingApprovals(),subset=pageItems(a);return titleBlock('Persetujuan kunjungan','Review rencana dan perubahan jadwal. Record selesai tetap ada pada histori.')+`<div class="listhead"><strong>${a.length} permintaan</strong></div><div class="records">${subset.map(t=>`<article class="record"><div class="recordtop">${badge(t.approval)}<small>${E(t.owner)}</small></div><h3>${E(t.purpose)}</h3><p>${E(pname(t.profile))}</p>${contextLabel(t)}<div class="meta">${fmt(t.scheduled)}${t.pendingChange?'<br>Usulan '+fmt(t.pendingChange.scheduled)+'<br>'+E(t.pendingChange.reason):''}</div><div class="actions">${supervisors()?btn('Setujui',`approveVisit('${t.id}','Disetujui')`,true)+btn('Kembalikan',`approveVisit('${t.id}','Dikembalikan')`):''}${btn('Detail',`go('Aktivitas detail','${t.id}')`)}</div></article>`).join('')||empty('Tidak ada permintaan.')}</div>${pager(a.length)}<div class="panel"><h2>Koreksi data</h2>${db.corrections.filter(x=>x.status==='Menunggu'&&mine(x)).slice(0,10).map(x=>`<div class="miniitem"><b>${E(x.reason)}</b><p>${E(x.proposed)}</p>${supervisors()?btn('Validasi',`reviewCorrection('${x.id}','Disetujui')`):''}</div>`).join('')||empty('Tidak ada koreksi menunggu.')}</div>`}
function scaleNotifications(){let all=[];visible(db.tasks).filter(overdue).forEach(t=>all.push({title:'Follow-up overdue',note:t.purpose+' · '+pname(t.profile),action:`go('Aktivitas detail','${t.id}')`}));visible(db.opps).filter(overSla).forEach(o=>all.push({title:'Eskalasi over SLA',note:o.name+' · '+age(o)+' / '+stageLimit(o)+' hari',action:`go('Opportunity detail','${o.id}')`}));pendingApprovals().forEach(t=>all.push({title:'Rencana menunggu review',note:t.purpose+' · '+pname(t.profile),action:"go('Persetujuan')"}));let slice=pageItems(all);return titleBlock('Pusat perhatian','Prioritas overdue, SLA dan persetujuan. ')+`<div class="listhead"><strong>${all.length.toLocaleString('id-ID')} notifikasi</strong></div><div class="panel">${slice.map(n=>`<button class="notifrow" onclick="${n.action}"><span class="notifdot"></span><span><strong>${E(n.title)}</strong><small>${E(n.note)}</small></span><b>↗</b></button>`).join('')||empty('Tidak ada notifikasi.')}</div>${pager(all.length)}`}
function scaleBanner(){return `<div class="datasetbar"><span><b>${db.largeData?'SKENARIO DATA BESAR':'DATA DEMO'}</b><small>${db.profiles.length.toLocaleString('id-ID')} profil · ${db.opps.length.toLocaleString('id-ID')} peluang · ${db.tasks.length.toLocaleString('id-ID')} task</small></span><button onclick="scenarioDialog()">${db.largeData?'Ganti skenario':'Kelola data'}</button></div>`}
const contentBeforeScale=renderContent;
renderContent=function(){migrate();if(['Agenda','Leads','Peluang','Nasabah'].includes(view))$('#app').innerHTML=scaleList();else if(view==='Monitoring')$('#app').innerHTML=largeMonitor();else if(view==='Persetujuan')$('#app').innerHTML=scaleApprovals();else if(view==='Notifikasi')$('#app').innerHTML=scaleNotifications();else contentBeforeScale();if(['Agenda','Leads','Peluang','Nasabah','Monitoring','Lainnya','Pengaturan'].includes(view))$('#app').insertAdjacentHTML('afterbegin',scaleBanner())};
function dateOffset(n){let d=new Date(demoToday()+'T12:00:00+08:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function makeLargeData(count=1000){let d=seed();for(let k of ['profiles','leads','opps','tasks','activities','audit','applications','corrections'])d[k]=[];d.largeData=true;d.rfiDemo=true;d.config.stageSla={'Kebutuhan':3,'Pembahasan':5,'Persiapan':7,'Keputusan':3};let sectors=['Pangan','Niaga','Mandiri','Lestari','Utama','Sentosa','Bersama','Cemerlang'],places=['Denpasar','Gianyar','Badung','Tabanan','Singaraja'];for(let i=0;i<count;i++){d.profiles.push({id:'DP'+String(i+1).padStart(4,'0'),name:(i%3===0?'CV ':'PT ')+sectors[i%8]+' '+places[Math.floor(i/8)%5]+' '+String(i+1).padStart(4,'0'),contact:['Made Aditya','Ni Luh Ratna','Komang Putri','Kadek Wayan'][i%4],phone:'0812'+String(10000000+i),address:'Jl. Usaha No. '+(i+1)+', '+places[i%5],relation:i<count*.6?'Prospect':'Customer',owner:owners[i%2],occupation:i%2?'Distribusi':'Produksi'});}let lc=Math.floor(count*.6),oc=Math.floor(count*1.2),tc=count*5,ac=Math.floor(count*1.5);for(let i=0;i<lc;i++){let converted=i%5===0;d.leads.push({id:'DL'+String(i+1).padStart(4,'0'),profile:d.profiles[i].id,source:['Input Lead','Referral Lead','Digital Lead','Campaign Lead','Existing Customer Lead'][i%5],referral:i%5===1?'Referral '+(i%30+1):'',product:['Kredit Produktif','KUR','Deposito','Tabungan'][i%4],need:'Kebutuhan usaha '+sectors[i%8],owner:owners[i%2],status:converted?'Converted':i%7===0?'Closed':i%2?'In qualification':'New',qualification:converted?'Qualified':i%3?'Perlu informasi':'Qualified',grade:quals[i%4],created:dateOffset(-i%90),recorded:now()})}for(let i=0;i<oc;i++){let p=d.profiles[i%count],outcome=i%11===0?'Won':i%13===0?'Lost':'Aktif';d.opps.push({id:'DO'+String(i+1).padStart(4,'0'),profile:p.id,lead:i<lc&&i%5===0?d.leads[i].id:'',name:['Modal kerja','Investasi usaha','Penempatan deposito','Tambahan layanan'][i%4]+' / '+p.name,product:['Kredit Produktif','KUR','Deposito','Layanan baru'][i%4],type:p.relation==='Customer'?'Expansion':'New business',need:'Pengembangan kebutuhan '+p.name,value:(i%25+1)*50000000,basis:i%4===2?'Penempatan dana':i%4===3?'Total kontrak':'Plafon indikatif',owner:p.owner,stage:stages[Math.floor(i/2)%4],entered:dateOffset(-(i%17)),created:dateOffset(-(i%90)),closing:dateOffset(i%35),outcome,reason:outcome==='Lost'?['Harga / penawaran','Kebutuhan ditunda','Memilih penyedia lain'][i%3]:'',probability:[20,35,50,65,80][i%5],target:'Target Q4 / '+p.owner})}for(let i=0;i<tc;i++){let o=d.opps[i%oc],p=d.profiles.find(p=>p.id===o.profile),off=(i%66)-20,type=['Telepon','Kunjungan','Meeting','Cek dokumen'][Math.floor(i/2)%4],status=i%6===0?'Selesai':o.outcome!=='Aktif'?'Dibatalkan':'Terjadwal',t={id:'DT'+String(i+1).padStart(5,'0'),profile:p.id,opp:i%5===0?'':o.id,lead:i%5===0&&i%lc<lc?d.leads[i%lc].id:'',type,purpose:['Konfirmasi kebutuhan','Survey lokasi usaha','Pembahasan dokumen','Tindak lanjut penawaran'][Math.floor(i/2)%4]+' '+String(i+1),owner:p.owner,scheduled:dateOffset(off)+'T'+['09:00','10:00','13:00','15:00'][i%4],due:dateOffset(off)+'T17:00',status};if(t.lead){t.profile=d.leads[i%lc].profile;t.owner=d.leads[i%lc].owner}if(type==='Kunjungan'){t.approval=i%3===0?'Menunggu':'Disetujui';t.approvalHistory=[{time:now(),actor:'Data demo',status:t.approval,note:'Fixture untuk review alur'}]}d.tasks.push(t)}for(let i=0;i<ac;i++){let t=d.tasks[i];d.activities.push({id:'DA'+String(i+1).padStart(5,'0'),profile:t.profile,opp:t.opp,lead:t.lead,task:t.status==='Selesai'?t.id:'',owner:t.owner,type:t.type,result:i%2?'Tertarik':'Perlu tindak lanjut',note:'Catatan simulasi riwayat aktivitas '+(i+1),occurred:dateOffset(-i%30)+'T10:00',recorded:now()})}d.audit=[{id:'DATASET',action:'Muat skenario data besar',object:'demo',detail:count+' profil / '+lc+' lead / '+oc+' peluang / '+tc+' task',actor:'Data demo',time:now()}];return d}
function scenarioDialog(){modal('Pilih skenario simulasi',`<p>Ganti data demo pada link ini. Ekspor terlebih dahulu jika ingin menyimpan perubahan yang sedang dicoba.</p>`+select('Ukuran skenario','size',['1.000 profil / 5.000 task','100 profil / 500 task','Skenario awal'])+`<p class="hint">Data sepenuhnya sintetis. Link CMS dan mobile tetap terpisah. Ini menguji pengalaman navigasi data, bukan performa backend.</p>`,f=>{let next=f.size==='Skenario awal'?seed():makeLargeData(f.size.startsWith('1.000')?1000:100);try{localStorage.setItem(key,JSON.stringify(next))}catch(e){throw Error('Penyimpanan browser penuh. Ekspor data lalu gunakan skenario 100 profil.')}db=next;migrate();resetLists();go(mobile?'Agenda':'Monitoring');return true})}
// Searchable profile picker and dependent opportunity selection.
function taskPickerResults(value){let list=$('#profileResults');if(!list)return;let a=visible(db.profiles).filter(p=>!value||[p.name,p.phone,p.contact].join(' ').toLowerCase().includes(value.toLowerCase())),top=a.slice(0,6);list.innerHTML=top.map(p=>`<button type="button" onclick="chooseTaskProfile('${p.id}')"><strong>${E(p.name)}</strong><small>${E(p.contact)} · ${p.relation==='Customer'?'Nasabah':'Lead'}</small></button>`).join('')+`<small class="pickercount">${a.length} hasil${a.length>6?' · Persempit dengan nama atau nomor kontak':''}</small>`}
function chooseTaskProfile(pid){let p=profile(pid);$('#taskProfile').value=pid;$('#profileQuery').value=p.name;$('#profileResults').innerHTML='';fillTaskOpportunities(pid)}
function fillTaskOpportunities(pid,oid=''){let a=visible(db.opps).filter(o=>o.profile===pid&&o.outcome==='Aktif'),el=$('#taskOpp');if(!el)return;el.innerHTML=`<option value="">Aktivitas umum / penjajakan</option>`+a.map(o=>`<option value="${o.id}" ${o.id===oid?'selected':''}>${E(o.name)}</option>`).join('');$('#opportunityHelp').textContent=a.length?`${a.length} opportunity aktif milik profil ini. Pilih jika aktivitas membahas peluang tertentu.`:'Belum ada opportunity aktif. Task tetap dapat dibuat untuk penjajakan atau relationship.'}
newTask=function(pid='',oid='',lid=''){if(!pid&&oid)pid=opp(oid)?.profile||'';let p=profile(pid);modal('Tambah Task',`<p class="formintro">Untuk siapa, kebutuhan apa, lalu kapan dilakukan.</p><input type="hidden" id="taskProfile" name="profile" value="${E(pid)}"><label>Lead / Nasabah<input id="profileQuery" autocomplete="off" placeholder="Ketik nama atau nomor kontak" value="${E(p?.name||'')}" ${pid?'readonly':''} oninput="document.querySelector('#taskProfile').value='';document.querySelector('#taskOpp').innerHTML='<option value=&quot;&quot;>Pilih profil dahulu</option>';taskPickerResults(this.value)"></label><div id="profileResults" class="pickerresults"></div><label>Opportunity terkait (jika ada)<select name="opp" id="taskOpp"><option value="">Pilih profil dahulu</option></select></label><p id="opportunityHelp" class="microhelp">Pilihan opportunity mengikuti lead/nasabah yang dipilih.</p>`+select('Jenis aktivitas','type',['Telepon','Kunjungan','Meeting','Cek dokumen'])+visitFields({owner:opp(oid)?.owner||p?.owner})+sectionToggle('Detail meeting',field('Peserta','participants')+area('Agenda','meetingAgenda'))+`<p class="hint">Kunjungan memerlukan approval supervisor. Jadwal WITA.</p>`,f=>{let p=profile(f.profile);if(!p||!mine(p))throw Error('Pilih lead atau nasabah dari hasil pencarian.');let o=f.opp?opp(f.opp):null;if(o&&(o.profile!==p.id||!mine(o)||o.outcome!=='Aktif'))throw Error('Opportunity harus aktif dan milik profil yang sama.');if(parseCRMDate(f.due)<parseCRMDate(f.scheduled))throw Error('Deadline tidak boleh sebelum jadwal.');let linkedLead=lid&&db.leads.find(l=>l.id===lid&&l.profile===p.id)?lid:'';let t={...f,id:uid('T'),profile:p.id,opp:o?.id||'',lead:o?'':linkedLead,status:'Terjadwal'};if(activityKind(t.type)==='Kunjungan'){t.approval='Menunggu';t.approvalHistory=[{time:now(),actor:actor(),status:'Diajukan',note:'Rencana baru'}]}db.tasks.push(t);if(o)delete o.review;record('Rencana aktivitas',t.id,(o?'Opportunity '+o.id:'Aktivitas profil')+' / '+f.purpose)});if(pid)fillTaskOpportunities(pid,oid);else taskPickerResults('')};

pendingApprovals=function(){return db.tasks.filter(t=>activityKind(t.type)==='Kunjungan'&&isOpen(t)&&['Menunggu','Perubahan diajukan'].includes(t.approval)&&mine(t))};
newOpp=function(pid='',lid=''){let l=db.leads.find(x=>x.id===lid);if(l&&l.qualification!=='Qualified')return toast('Lead perlu Qualified sebelum konversi.');let p=profile(pid);modal(l?'Konversi ke opportunity':'Opportunity baru',`<input type="hidden" id="taskProfile" name="profile" value="${E(pid)}"><label>Lead / Nasabah<input id="profileQuery" autocomplete="off" placeholder="Cari nama atau kontak" value="${E(p?.name||'')}" ${pid?'readonly':''} oninput="document.querySelector('#taskProfile').value='';taskPickerResults(this.value)"></label><div id="profileResults" class="pickerresults"></div>`+field('Nama peluang','name',l?.need||'','text',true)+select('Jenis peluang','type',['New business','Expansion','Renewal'],p?.relation==='Customer'?'Expansion':'New business')+select('Produk / layanan','product',['Kredit Produktif','Kredit Konsumtif','KUR','Tabungan','Giro','Deposito','Layanan baru','Renewal'],l?.product)+area('Kebutuhan','need',l?.need||'',true)+sectionToggle('Nilai, probability dan target',field('Nilai indikatif (Rp, opsional)','value','','number')+select('Basis nilai','basis',['Plafon indikatif','Penempatan dana','Total kontrak','Sekali bayar','Bulanan','Tahunan'])+field('Probability (%)','probability','35','number',true)+field('Target closing','closing',dateOffset(14),'date',true)+field('Target bisnis / periode','target'))+ownerSelect(l?.owner||p?.owner)+`<p class="hint">Profil yang sama dapat memiliki beberapa opportunity. Konversi tidak otomatis mengubah Lead menjadi Nasabah.</p>`,f=>{let p=profile(pid||f.profile);if(!p||!mine(p))throw Error('Pilih profil dari hasil pencarian.');if(Number(f.probability)<0||Number(f.probability)>100)throw Error('Probability 0-100%');let o={...f,id:uid('O'),profile:p.id,lead:lid,value:f.value===''?null:Number(f.value),probability:Number(f.probability),stage:(activeMaster('stages').find(s=>s.type==='process')?.name||'Kebutuhan'),entered:now(),created:today(),outcome:'Aktif'};db.opps.push(o);if(l)l.status='Converted';record('Buat opportunity',o.id,lid?'Konversi lead '+lid:'Profil existing');go('Opportunity detail',o.id)});if(!pid)taskPickerResults('')};
let backListState=null;
const goBeforeRestore=go;
go=function(v,id=''){if(['Agenda','Leads','Peluang','Nasabah','Persetujuan','Notifikasi'].includes(view)&&/detail/.test(v))backListState={view,listPage,listQuery,listOwner,listStatus,listSource,listProduct,listRelation,listGrade,agendaRange,agendaType,listPeriod,stageFilter,listKind};goBeforeRestore(v,id)};
function backToResults(){if(!backListState)return go(mobile?'Agenda':'Monitoring');let s=backListState;view=s.view;focus='';({listPage,listQuery,listOwner,listStatus,listSource,listProduct,listRelation,listGrade,agendaRange,agendaType,listPeriod,stageFilter,listKind}=s);render();document.querySelector('main')?.scrollTo(0,0)}
const contentBeforeReturn=renderContent;
renderContent=function(){contentBeforeReturn();if(/detail/.test(view)&&backListState)$('#app').insertAdjacentHTML('afterbegin',`<div class="returnrow">${btn('‹ Kembali ke hasil '+backListState.view,'backToResults()')}<small>Filter dan halaman tetap tersimpan</small></div>`)};

